package com.zipai.web;
import com.zipai.domain.User;import com.zipai.service.*;import jakarta.servlet.http.HttpSession;import java.io.IOException;import java.util.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/api/defense") public class DefenseAnalysisController{private final RegistryDocumentAnalysisService analysis;private final DefenseReportService reports;private final AuthService auth;public DefenseAnalysisController(RegistryDocumentAnalysisService a,DefenseReportService reports,AuthService auth){analysis=a;this.reports=reports;this.auth=auth;}
 @PostMapping(value="/registry-analysis",consumes="multipart/form-data")Map<String,Object> analyze(@RequestPart("file")MultipartFile file,HttpSession session)throws IOException{User user=auth.required(session);byte[] bytes=file.getBytes();Map<String,Object>result=analysis.analyze(file.getOriginalFilename(),file.getContentType(),bytes);return Map.of("analysis",result,"report",reports.createRegistry(user,file.getOriginalFilename(),file.getContentType(),bytes,result));}}
